# Deny by default: one policy function used by every handler.
def authorize(user, action, resource):
    if action not in ALLOWED_ACTIONS_BY_ROLE.get(user.role, set()):
        audit.log(user.id, action, resource.id, decision='deny')
        return False                      # BFLA: wrong role
    if resource.owner_id != user.id and user.role != 'admin':
        audit.log(user.id, action, resource.id, decision='deny')
        return False                      # BOLA: not the owner
    audit.log(user.id, action, resource.id, decision='allow')
    return True

def invoice_view(invoice):
    # API3: explicit allow-list of fields, never the raw row
    return {'id': invoice.id, 'total': invoice.total, 'status': invoice.status}

